<template><main class="paper-shell"><div class="paper-container admin-container"><header class="paper-workspace-header"><div><div class="paper-page-eyebrow">Knowledge Base / Administration</div><h1 class="paper-page-title">Service diagnostics</h1><p class="paper-page-description">Verify every dependency used by collection, parsing, extraction, and discovery.</p></div><button class="paper-button" :disabled="busy" @click="runAll">Test all</button></header><LiteratureAdminNav/><p v-if="error" class="admin-notice error">{{error}}</p><section class="service-grid"><article v-for="service in services" :key="service.id" class="paper-panel service-card"><div class="service-heading"><h2>{{service.label}}</h2><span :class="result(service.id)?.ok===true?'ok':result(service.id)?.ok===false?'bad':''">{{status(service.id)}}</span></div><p>{{service.description}}</p><button class="admin-action" :disabled="testing===service.id" @click="test(service.id)">{{testing===service.id?'Testing…':'Test connection'}}</button><pre v-if="result(service.id)">{{pretty(result(service.id))}}</pre></article></section><section class="paper-panel admin-card"><h2>Knowledge graph diagnostics</h2><button class="admin-action" @click="graphCheck">Run graph diagnostics</button><AdminObjectTable :value="graph"/></section></div></main></template>
<script setup>
import '~/assets/paper-platform.css';import {authState,loadCurrentUser} from '~/utils/auth';definePageMeta({middleware:'auth-client'});useHead({title:'Literature Diagnostics - OpenIsle'})
const api=useLiteratureAdmin(),testing=ref(''),busy=ref(false),results=ref({}),graph=ref({}),error=ref('');const services=[{id:'llm',label:'LLM extraction',description:'Knowledge-card and method extraction.'},{id:'embedding',label:'Embedding',description:'Vector and hybrid semantic search.'},{id:'mineru',label:'MinerU parser',description:'Structured PDF parsing service.'},{id:'wos',label:'Web of Science',description:'Licensed metadata source; optional API key.'},{id:'scopus',label:'Scopus',description:'Licensed metadata source; optional API key.'}]
const ensure=async()=>{if(!authState.role)await loadCurrentUser();if(authState.role!=='ADMIN'){await navigateTo('/literature/workflow');return false}return true};const result=id=>results.value[id];const status=id=>!result(id)?'Not tested':result(id).ok===false||result(id).success===false?'Unavailable':'Available';const pretty=v=>JSON.stringify(v,null,2)
const test=async id=>{testing.value=id;error.value='';try{results.value[id]=await api.post('/test/connection',{service:id})}catch(e){results.value[id]={ok:false,error:e?.data?.message||e.message}}finally{testing.value=''}};const runAll=async()=>{busy.value=true;for(const s of services)await test(s.id);busy.value=false};const graphCheck=async()=>{try{graph.value=await api.get('/graph/diagnostics')}catch(e){error.value=e?.data?.message||e.message}};onMounted(ensure)
</script><style scoped src="~/assets/literature-admin.css"></style><style scoped>.service-heading{display:flex;justify-content:space-between;gap:12px}.service-heading span{color:var(--paper-muted);font-size:11px;font-weight:800;text-transform:uppercase}.service-heading .ok{color:#236b52}.service-heading .bad{color:#a33d34}.service-card pre{max-height:150px;overflow:auto;padding:10px;background:#f3f6f8;font-size:10px;white-space:pre-wrap}</style>
